import json,re
def scan(f,pat,maxn=6,pre=350,post=450):
    n=0
    for i,line in enumerate(open(f,encoding='utf-8',errors='replace'),1):
        if not re.search(pat,line): continue
        r=json.loads(line)
        msg=r.get('message') or {}
        c=msg.get('content')
        blocks=[]
        if isinstance(c,str): blocks=[('str',c)]
        elif isinstance(c,list):
            for b in c:
                if not isinstance(b,dict):continue
                t=b.get('type')
                if t in('text','thinking'): blocks.append((t,b.get('text') or b.get('thinking','')))
                elif t=='tool_use': blocks.append(('tool:'+b['name'],json.dumps(b['input'],ensure_ascii=False)))
                elif t=='tool_result': blocks.append(('res',json.dumps(b.get('content'),ensure_ascii=False)))
        for kind,s in blocks:
            m=re.search(pat,s)
            if m:
                print(f'--- {f.split("/")[-1]}:{i} [{kind}] {r.get("timestamp")}')
                print('  ',s[max(0,m.start()-pre):m.start()+post].replace('\n','\n   '))
                n+=1;break
        if n>=maxn: break
